import cadquery as cq

length = 0.33
width = 0.22
height = 0.19

result = (
    cq.Workplane("XY")
    .slot2D(length, width)
    .extrude(height)
)

try:
    result = result.edges("|X or |Y or %CIRCLE").fillet(0.02)
except Exception:
    try:
        result = result.faces(">Z or <Z").edges().fillet(0.02)
    except Exception:
        pass
